// OTHVM — final output normalizer: compact JSON, capped strings, capped total size
const out = [];
let total = 0;
for (const item of $input.all().slice(0, 25)) {
  if (item.error) { const e = item.error; const msg = [e.message, e.description].filter((x) => typeof x === 'string' && x).join(' — ') || 'unknown error'; out.push({ json: { ok: false, error: msg.slice(0, 400) } }); continue; }
  const j = item.json || {};
  if (j.ok === false || (Object.keys(j).length === 1 && 'error' in j)) { const e = j.error; const msg = typeof e === 'string' ? e : (e && typeof e === 'object' ? ([e.message, e.description].filter((x) => typeof x === 'string' && x).join(' — ') || 'unknown error') : String(e || 'unknown error')); out.push({ json: { ok: false, error: msg.slice(0, 400) } }); continue; }
  if (typeof j.operation === 'string' && /^[a-z]+[A-Za-z0-9]*.[a-zA-Z][A-Za-z0-9]*$/.test(j.operation) && j.id === undefined && j.ok !== true) { out.push({ json: { ok: false, error: 'الأداة مرجّعتش نتيجة تنفيذ حقيقية — الأغلب فشل (مصادقة أو اتصال أو مدخلات ناقصة). راجع الإعدادات أو جرّب تاني.' } }); continue; }
  const o = {};
  for (const [k, v] of Object.entries(j)) {
    if (v === null || v === undefined) continue;
    if (typeof v === 'string') o[k] = v.length > 400 ? v.slice(0, 400) + '\u2026' : v;
    else if (typeof v === 'object') { const s = JSON.stringify(v); o[k] = s.length > 500 ? s.slice(0, 500) + '\u2026' : v; }
    else o[k] = v;
  }
  if (!Object.keys(o).length) continue;
  const s = JSON.stringify(o);
  if (total + s.length > 12000) break;
  total += s.length;
  out.push({ json: o });
}
return out.length ? out : [{ json: { ok: true, note: 'no results' } }];

